"""MeshGenerator factory — extracted from mesh_generator.py (issue #2351).

This module provides the ``MeshGenerator`` factory class that selects and
instantiates the appropriate backend implementation.  Moving it here reduces
``mesh_generator.py`` from 1,645 lines while keeping public imports unchanged
via the ``MeshGenerator`` re-export in that module.
"""

from __future__ import annotations

from typing import Any

from src.shared.python.logging_pkg.logging_config import get_logger

from .mesh_generator_makehuman import MakeHumanMeshGenerator
from .mesh_generator_models import MeshGeneratorBackend, MeshGeneratorInterface
from .mesh_generator_primitive import PrimitiveMeshGenerator
from .mesh_generator_smplx import SMPLXMeshGenerator

logger = get_logger(__name__)


class MeshGenerator:
    """Factory class for creating mesh generators.

    Provides a unified interface to multiple mesh generation backends.
    """

    _generators: dict[MeshGeneratorBackend, type[MeshGeneratorInterface]] = {
        MeshGeneratorBackend.PRIMITIVE: PrimitiveMeshGenerator,
        MeshGeneratorBackend.MAKEHUMAN: MakeHumanMeshGenerator,
        MeshGeneratorBackend.SMPLX: SMPLXMeshGenerator,
    }

    @classmethod
    def create(
        cls,
        backend: MeshGeneratorBackend | str = MeshGeneratorBackend.PRIMITIVE,
        **kwargs: Any,
    ) -> MeshGeneratorInterface:
        """Create a mesh generator for the specified backend.

        Args:
            backend: Backend to use (enum value or string name).
            **kwargs: Backend-specific initialisation options.

        Returns:
            MeshGeneratorInterface instance.

        Raises:
            ValueError: If the backend string is not recognised.
        """
        if isinstance(backend, str):
            backend = MeshGeneratorBackend(backend.lower())

        generator_class = cls._generators.get(backend)
        if generator_class is None:
            raise ValueError(f"Unknown backend: {backend}")

        return generator_class(**kwargs)

    @classmethod
    def get_available_backends(cls) -> list[MeshGeneratorBackend]:
        """Return list of currently available backends."""
        available = []
        for backend, generator_class in cls._generators.items():
            try:
                generator = generator_class()
                if generator.is_available:
                    available.append(backend)
            except (ImportError, RuntimeError, OSError) as e:
                logger.debug("Backend %s not available: %s", backend.value, e)
        return available

    @classmethod
    def get_best_available(cls) -> MeshGeneratorInterface:
        """Return the best currently available mesh generator.

        Preference order: MakeHuman > SMPL-X > Primitive.
        """
        preference = [
            MeshGeneratorBackend.MAKEHUMAN,
            MeshGeneratorBackend.SMPLX,
            MeshGeneratorBackend.PRIMITIVE,
        ]

        for backend in preference:
            try:
                generator = cls.create(backend)
                if generator.is_available:
                    return generator
            except (ImportError, RuntimeError, OSError) as e:
                logger.debug("Backend %s not available: %s", backend.value, e)
                continue

        # Final fallback
        return PrimitiveMeshGenerator()
